```java
package com.example.gdxstagesim;

import com.badlogic.gdx.ApplicationAdapter;
import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.scenes.scene2d.Actor;
import com.badlogic.gdx.scenes.scene2d.actions.Actions;
import com.badlogic.gdx.scenes.scene2d.actions.MoveByAction;
import com.badlogic.gdx.utils.Array;

import java.io.BufferedWriter;
import java.io.OutputStreamWriter;
import java.io.FileOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.CountDownLatch;

public class SceneSimApplication extends ApplicationAdapter {
    private final String scriptPath;
    private final String outputPath;
    private final CountDownLatch latch;

    private float dt;
    private int totalTicks;
    private int tickCount = 0;

    private final List<Actor> actors = new ArrayList<>();
    private final Map<String, Actor> actorsById = new LinkedHashMap<>();

    public SceneSimApplication(String scriptPath, String outputPath, CountDownLatch latch) {
        this.scriptPath = scriptPath;
        this.outputPath = outputPath;
        this.latch = latch;
    }

    @Override
    public void create() {
        String content = Gdx.files.absolute(scriptPath).readString("UTF-8");
        parseScript(content);
    }

    @Override
    public void render() {
        if (tickCount >= totalTicks) {
            Gdx.app.exit();
            return;
        }
        for (Actor actor : actors) {
            actor.act(dt);
        }
        tickCount++;
        if (tickCount >= totalTicks) {
            Gdx.app.exit();
        }
    }

    @Override
    public void dispose() {
        writeOutput();
        latch.countDown();
    }

    private void parseScript(String content) {
        boolean dtSet = false;
        boolean ticksSet = false;
        boolean actorSeen = false;

        // Track moveby per actor
        // ...

        String[] lines = content.split("\n", -1);
        for (String rawLine : lines) {
            String line = rawLine.trim();
            if (line.isEmpty()) continue;
            if (line.startsWith("#")) continue;

            String[] tokens = line.split("\\s+");
            String directive = tokens[0].toLowerCase(Locale.ROOT);

            switch (directive) {
                case "dt":
                    if (dtSet) throw error("dt declared more than once");
                    if (actorSeen) throw error("dt must appear before actor directives");
                    dt = Float.parseFloat(tokens[1]);
                    if (dt <= 0) throw error("dt must be > 0");
                    dtSet = true;
                    break;
                case "ticks":
                    if (ticksSet) throw error("ticks declared more than once");
                    if (actorSeen) throw error("ticks must appear before actor directives");
                    totalTicks = Integer.parseInt(tokens[1]);
                    if (totalTicks < 0) throw error("ticks must be >= 0");
                    ticksSet = true;
                    break;
                case "actor":
                    if (!dtSet || !ticksSet) throw error("dt and ticks must appear before actor directives");
                    actorSeen = true;
                    String id = tokens[1];
                    validateId(id);
                    if (actorsById.containsKey(id)) throw error("duplicate actor id: " + id);
                    float x = Float.parseFloat(tokens[2]);
                    float y = Float.parseFloat(tokens[3]);
                    Actor actor = new Actor();
                    actor.setName(id);
                    actor.setPosition(x, y);
                    actors.add(actor);
                    actorsById.put(id, actor);
                    break;
                case "moveby":
                    String mid = tokens[1];
                    Actor target = actorsById.get(mid);
                    if (target == null) throw error("unknown actor: " + mid);
                    float dx = Float.parseFloat(tokens[2]);
                    float dy = Float.parseFloat(tokens[3]);
                    float duration = Float.parseFloat(tokens[4]);
                    if (duration < 0) throw error("duration must be >= 0");
                    // Check at most one moveby per actor
                    if (target.getActions().size > 0) throw error("at most one moveby per actor: " + mid);
                    MoveByAction action = Actions.moveBy(dx, dy, duration);
                    target.addAction(action);
                    break;
                default:
                    throw error("unknown directive: " + directive);
            }
        }

        if (!dtSet) throw error("dt not declared");
        if (!ticksSet) throw error("ticks not declared");
    }

    private void writeOutput() {
        try (BufferedWriter writer = new BufferedWriter(
                new OutputStreamWriter(new FileOutputStream(outputPath), StandardCharsets.UTF_8))) {
            for (Actor actor : actors) {
                String id = actor.getName();
                writer.write(String.format(Locale.ROOT, "%s=%.6f,%.6f", id, actor.getX(), actor.getY()));
                writer.write("\n");
            }
        } catch (IOException e) {
            throw new RuntimeException("Failed to write output file", e);
        }
    }

    private void validateId(String id) {
        if (!id.matches("[A-Za-z0-9_]+")) {
            throw error("invalid actor id: " + id);
        }
    }

    private RuntimeException error(String msg) {
        return new RuntimeException("Script error: " + msg);
    }
}
